export default function ChatInterface({ initialInput = '' }: { initialInput?: string }) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState(initialInput);
  const [busy, setBusy] = useState(false);
  const [useRag, setUseRag] = useState(false);
  const [selectedModel, setSelectedModel] = useState<GeminiModel>('gemini-2.5-flash');
  const [useThinkingMode, setUseThinkingMode] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null); // To help with smooth scrolling
  const [isAtBottom, setIsAtBottom] = useState(true);
  const [showJumpButton, setShowJumpButton] = useState(false);

  // --- Voice Input State ---
  const [isRecordingAudio, setIsRecordingAudio] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const inputAudioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    // If the tool 'transcribe' was selected, prompt for a file.
    if (initialInput.trim().toLowerCase() === 'transcribe') {
      fileRef.current?.click();
      setInput(''); // Clear the input so it doesn't stay as 'transcribe'
    } else {
      setInput(initialInput);
    }
  }, [initialInput]);

  // Manages the isAtBottom state based on user scrolling
  useEffect(() => {
    const container = messagesContainerRef.current;
    if (!container) return;

    const handleScroll = () => {
      const threshold = 24; // Small pixel threshold to consider "at bottom"
      const isScrolledToBottom = container.scrollHeight - container.clientHeight <= container.scrollTop + threshold;
      setIsAtBottom(isScrolledToBottom);
      if (isScrolledToBottom) {
        setShowJumpButton(false);
      }
    };

    container.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll(); // Initial check
    return () => container.removeEventListener('scroll', handleScroll);
  }, []);

  // Auto-scrolls on new messages only if the user is at the bottom, otherwise shows a jump button.
  useEffect(() => {
    if (isAtBottom) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    } else {
      // Show jump button if a new message from the assistant arrives while scrolled up.
      const lastMessage = messages[messages.length - 1];
      if (lastMessage?.role === 'assistant') {
        setShowJumpButton(true);
      }
    }
  }, [messages]);

  // Disable thinking mode if Pro model is not selected
  useEffect(() => {
    if (selectedModel !== 'gemini-2.5-pro') {
      setUseThinkingMode(false);
    }
  }, [selectedModel]);


  const push = (role: 'user' | 'assistant', text: string) => {
    const m: ChatMessage = {
      id: crypto.randomUUID(),
      role,
      text,
      createdAt: new Date().toISOString(),
    };
    setMessages((s) => [...s, m]);
    return m.id;
  }

  const submitMessage = useCallback(async (userText: string) => {
    if (!userText || busy) return;

    setInput('');
    push('user', userText);
    setBusy(true);

    const assistantMessageId = push('assistant', '');

    try {
      const { used_rag } = await chatTextStream(userText, useRag, selectedModel, useThinkingMode, (chunk) => {
        setMessages((s) => s.map(msg => 
          msg.id === assistantMessageId 
            ? { ...msg, text: msg.text + chunk } 
            : msg
        ));
      });

      // after stream finishes, update the message with the used_rag flag
      setMessages(s => s.map(msg => 
        msg.id === assistantMessageId 
          ? { ...msg, used_rag } 
          : msg
      ));

    } catch (e) {
      console.error(e);
      const errorMessage = 'i hit a snag talking to the server. is it running?';
      setMessages((s) => s.map(msg =>
        msg.id === assistantMessageId
          ? { ...msg, text: errorMessage }
          : msg
      ));
    } finally {
      setBusy(false);
    }
  }, [busy, useRag, selectedModel, useThinkingMode]);


  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    submitMessage(input.trim());
  }

  async function handleAudioFile(f: File) {
    push('user', `[audio file: ${f.name}]`);
    setBusy(true);
    const thinkingMessageId = push('assistant', 'transcribing audio with gemini flash...');

    try {
      const response = await chatAudio(f); // This API call will now use Vertex AI via backend
      const formattedResponse = `transcript:
${response.transcript}

summary:
${response.summary}

reply:
${response.reply}`;

      setMessages((s) => s.filter(m => m.id !== thinkingMessageId));
      push('assistant', formattedResponse);

    } catch (e) {
      console.error(e);
      setMessages((s) => s.filter(m => m.id !== thinkingMessageId));
      push('assistant', 'sorry, there was an error during transcription.');
    } finally {
      setBusy(false);
    }
  }

  const handleFileSelection = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (f) {
      if (f.type.startsWith('audio/')) {
        handleAudioFile(f);
      } else {
        push('assistant', 'i can only process audio files for transcription.');
      }
    }
    // Reset file input to allow selecting the same file again
    if (e.target) e.target.value = '';
  };

  const handleJumpToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // --- Voice Input Logic (using MediaRecorder for backend transcription) ---
  const handleToggleRecording = useCallback(async () => {
    if (isRecordingAudio) {
      // Stop recording
      mediaRecorderRef.current?.stop();
      setIsRecordingAudio(false);
    } else {
      // Start recording
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        if (inputAudioContextRef.current.state === 'suspended') {
          await inputAudioContextRef.current.resume();
        }

        mediaRecorderRef.current = new MediaRecorder(stream, { mimeType: 'audio/webm' });
        audioChunksRef.current = [];

        mediaRecorderRef.current.ondataavailable = (event) => {
          if (event.data.size > 0) {
            audioChunksRef.current.push(event.data);
          }
        };

        mediaRecorderRef.current.onstop = async () => {
          const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
          const audioFile = new File([audioBlob], `recorded_audio_${Date.now()}.webm`, { type: 'audio/webm' });
          stream.getTracks().forEach(track => track.stop()); // Stop microphone access
          await handleAudioFile(audioFile);
        };

        mediaRecorderRef.current.start();
        setIsRecordingAudio(true);
        setInput('listening for audio input...');
        setMessages(s => [...s, { id: crypto.randomUUID(), role: 'assistant', text: 'recording audio for transcription...' , createdAt: new Date().toISOString()}]);

      } catch (err) {
        console.error("Mic permission denied or failed to start recording:", err);
        alert("microphone permission is required for voice input.");
        setIsRecordingAudio(false);
        setInput('');
      }
    }
  }, [isRecordingAudio, handleAudioFile]);


  return (
    <section aria-label="Chat" className="w-full max-w-3xl mx-auto flex flex-col h-[calc(100vh-65px)]">
      <div ref={messagesContainerRef} role="list" className="relative flex-grow p-4 overflow-y-auto">
        {messages.map((m, i) => <React.Fragment key={m.id}><MessageItem m={m} busy={busy && i === messages.length - 1} /></React.Fragment>)}
        <div ref={messagesEndRef} />
        {showJumpButton && (
          <button
            onClick={handleJumpToBottom}
            className="absolute bottom-4 left-1/2 -translate-x-1/2 z-10 bg-indigo-600 text-white px-4 py-2 rounded-full shadow-lg hover:bg-indigo-700 transition-transform transform hover:scale-105 animate-fade-in text-sm"
            aria-label="Scroll to new messages"
          >
            New messages ↓
          </button>
        )}
      </div>
      <form onSubmit={onSubmit} className="bg-white/80 dark:bg-gray-900/80 backdrop-blur p-3 border-t border-gray-200 dark:border-gray-700" aria-label="Chat input">
        <div className="flex gap-2 items-center">
           <button
            type="button"
            onClick={handleToggleRecording}
            className={`p-3 border rounded-2xl shadow-sm hover:bg-gray-100 dark:hover:bg-gray-800 disabled:opacity-50 ${isRecordingAudio ? 'text-red-500 bg-red-50 dark:bg-red-900/20' : ''}`}
            aria-label={isRecordingAudio ? "stop recording audio" : "start recording audio for transcription"}
            disabled={busy}
          >
            {isRecordingAudio ? <StopCircle size={20} /> : <Mic size={20} />}
          </button>
          <button
            type="button"
            onClick={() => fileRef.current?.click()}
            className="p-3 border rounded-2xl shadow-sm hover:bg-gray-100 dark:hover:bg-gray-800 disabled:opacity-50"
            disabled={busy || isRecordingAudio}
            aria-label="Attach audio for transcription"
          >
            <Paperclip size={20} />
          </button>
          <input
            aria-label="Type a message"
            className="flex-1 border bg-gray-100 dark:bg-gray-800 border-gray-300 dark:border-gray-600 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder={isRecordingAudio ? "recording audio..." : "ask kor'tana…"}
            disabled={isRecordingAudio}
          />
          <RagToggle enabled={useRag} onChange={setUseRag} disabled={busy || isRecordingAudio} />
          <ModelSelector selectedModel={selectedModel} onChange={setSelectedModel} disabled={busy || isRecordingAudio} />
          {selectedModel === 'gemini-2.5-pro' && (
            <ThinkingModeToggle enabled={useThinkingMode} onChange={setUseThinkingMode} disabled={busy || isRecordingAudio} />
          )}
          <button type="submit" className="rounded-2xl px-4 py-3 border shadow-sm bg-indigo-600 text-white font-semibold hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed" disabled={busy || isRecordingAudio}>Send</button>
          <input
            ref={fileRef}
            type="file"
            className="sr-only"
            onChange={handleFileSelection}
            accept="audio/*"
          />
        </div>
        <p className="sr-only" aria-live="polite">
          {isRecordingAudio ? "recording audio for transcription" : ""}
          {busy ? "processing your request" : ""}
        </p>
        <p className="mt-2 text-xs text-gray-500 dark:text-gray-400 text-center">
          note: for continuous voice conversations, try the 'start a live conversation' tool on the dashboard.
        </p>
      </form>
    </section>
  );
}

