import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Mic, MicOff, Power, Activity, Volume2, AlertCircle } from 'lucide-react';

type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error';

export default function LiveConversation() {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [error, setError] = useState<string | null>(null);
  const [volume, setVolume] = useState(0); // For visualizer
  const [isMuted, setIsMuted] = useState(false);

  // Audio Contexts
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);

  // Stream & Processing
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const sourceNodeRef = useRef<MediaStreamAudioSourceNode | null>(null);

  // Playback State
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Session Control
  const sessionRef = useRef<any>(null);

  useEffect(() => {
    return () => {
      disconnectSession();
    };
  }, []);

  const connectSession = async () => {
    if (status === 'connected' || status === 'connecting') return;
    setStatus('connecting');
    setError(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key not found in environment.");

      const ai = new GoogleGenAI({ apiKey });

      // Initialize Audio Contexts
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      // Get Microphone Stream
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaStreamRef.current = stream;

      const config = {
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
          },
          systemInstruction: "You are Kor'tana, a helpful and concise AI assistant. You speak in a natural, conversational tone.",
        },
      };

      const sessionPromise = ai.live.connect({
        ...config,
        callbacks: {
          onopen: () => {
            setStatus('connected');
            setupAudioInput(sessionPromise);
          },
          onmessage: (msg: LiveServerMessage) => {
            handleServerMessage(msg);
          },
          onclose: () => {
            setStatus('disconnected');
            cleanupAudio();
          },
          onerror: (err: ErrorEvent) => {
            console.error("Session Error:", err);
            setError("Connection error. Please try again.");
            setStatus('error');
            cleanupAudio();
          }
        }
      });

      sessionRef.current = sessionPromise;

    } catch (e) {
      console.error("Connection Failed:", e);
      setError(e instanceof Error ? e.message : "Failed to connect to Live API");
      setStatus('error');
      cleanupAudio();
    }
  };

  const setupAudioInput = async (sessionPromise: Promise<any>) => {
    if (!inputAudioContextRef.current || !mediaStreamRef.current) return;

    const ctx = inputAudioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();

    sourceNodeRef.current = ctx.createMediaStreamSource(mediaStreamRef.current);
    processorRef.current = ctx.createScriptProcessor(4096, 1, 1);

    processorRef.current.onaudioprocess = (e) => {
      if (isMuted) return;

      const inputData = e.inputBuffer.getChannelData(0);

      // Calculate volume for visualizer
      let sum = 0;
      for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
      setVolume(Math.sqrt(sum / inputData.length));

      // Create PCM Blob
      const l = inputData.length;
      const int16 = new Int16Array(l);
      for (let i = 0; i < l; i++) {
        // Clamp and convert float32 to int16
        const s = Math.max(-1, Math.min(1, inputData[i]));
        int16[i] = s < 0 ? s * 0x8000 : s * 0x7FFF;
      }

      const base64Data = btoa(String.fromCharCode(...new Uint8Array(int16.buffer)));

      sessionPromise.then(session => {
        session.sendRealtimeInput({
          media: {
            mimeType: "audio/pcm;rate=16000",
            data: base64Data
          }
        });
      });
    };

    sourceNodeRef.current.connect(processorRef.current);
    processorRef.current.connect(ctx.destination);
  };

  const handleServerMessage = async (message: LiveServerMessage) => {
    const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;

    if (audioData && outputAudioContextRef.current) {
      const ctx = outputAudioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      // Decode base64 PCM
      const binaryString = atob(audioData);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);

      const int16Data = new Int16Array(bytes.buffer);
      const float32Data = new Float32Array(int16Data.length);
      for (let i = 0; i < int16Data.length; i++) {
        float32Data[i] = int16Data[i] / 32768.0;
      }

      const audioBuffer = ctx.createBuffer(1, float32Data.length, 24000);
      audioBuffer.getChannelData(0).set(float32Data);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      // Schedule playback
      const currentTime = ctx.currentTime;
      if (nextStartTimeRef.current < currentTime) {
        nextStartTimeRef.current = currentTime;
      }

      source.start(nextStartTimeRef.current);
      nextStartTimeRef.current += audioBuffer.duration;

      audioSourcesRef.current.add(source);
      source.onended = () => audioSourcesRef.current.delete(source);
    }

    if (message.serverContent?.interrupted) {
      audioSourcesRef.current.forEach(src => src.stop());
      audioSourcesRef.current.clear();
      nextStartTimeRef.current = 0;
    }
  };

  const disconnectSession = () => {
    if (sessionRef.current) {
      sessionRef.current.then((s: any) => s.close());
      sessionRef.current = null;
    }
    cleanupAudio();
    setStatus('disconnected');
  };

  const cleanupAudio = () => {
    if (mediaStreamRef.current) {
      mediaStreamRef.current.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
    }
    if (processorRef.current) {
      processorRef.current.disconnect();
      processorRef.current = null;
    }
    if (sourceNodeRef.current) {
      sourceNodeRef.current.disconnect();
      sourceNodeRef.current = null;
    }
    inputAudioContextRef.current?.close();
    outputAudioContextRef.current?.close();
    setVolume(0);
  };

  const toggleMute = () => setIsMuted(!isMuted);

  return (
    <div className="flex flex-col items-center justify-center min-h-[calc(100vh-80px)] p-6 animate-fade-in">
      <div className="relative w-full max-w-lg bg-white dark:bg-gray-800 rounded-3xl shadow-xl overflow-hidden border border-gray-200 dark:border-gray-700">

        {/* Header */}
        <div className="bg-gray-50 dark:bg-gray-900/50 p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Activity className={status === 'connected' ? 'text-green-500' : 'text-gray-400'} size={20} />
            Live Conversation
          </h2>
          <div className={`px-3 py-1 rounded-full text-xs font-semibold uppercase tracking-wider ${
            status === 'connected' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
            status === 'connecting' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' :
            status === 'error' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' :
            'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400'
          }`}>
            {status}
          </div>
        </div>

        {/* Visualizer Area */}
        <div className="h-64 flex flex-col items-center justify-center relative bg-gradient-to-b from-white to-gray-50 dark:from-gray-800 dark:to-gray-900 transition-colors duration-500">

          {/* Status Rings */}
          <div className="relative flex items-center justify-center">
            {status === 'connected' && (
              <>
                <div className="absolute w-32 h-32 rounded-full border-2 border-indigo-500/20 animate-[pulse_3s_ease-in-out_infinite]" 
                     style={{ transform: `scale(${1 + volume * 5})` }} />
                <div className="absolute w-24 h-24 rounded-full border border-indigo-500/40 animate-[pulse_2s_ease-in-out_infinite]"
                     style={{ transform: `scale(${1 + volume * 3})` }} />
              </>
            )}

            {/* Core Orb */}
            <div className={`w-16 h-16 rounded-full flex items-center justify-center transition-all duration-500 shadow-lg z-10 ${
              status === 'connected' ? 'bg-indigo-500 shadow-indigo-500/50' : 
              status === 'connecting' ? 'bg-blue-500 animate-pulse' :
              status === 'error' ? 'bg-red-500' :
