import React from "react";

interface AppErrorBoundaryProps {
  children: React.ReactNode;
}

interface AppErrorBoundaryState {
  error?: any;
}

export class AppErrorBoundary extends React.Component<AppErrorBoundaryProps, AppErrorBoundaryState> {
  // Note: Refactored to use a class property for state initialization instead of a constructor.
  // This is a more modern approach and resolves the error where 'this.props' was not
  // being correctly recognized by TypeScript.
  state: AppErrorBoundaryState = { error: undefined };

  static getDerivedStateFromError(error: any) {
    return { error };
  }

  componentDidCatch(error: any, errorInfo: any) {
    console.error("Uncaught error in App:", error, errorInfo);
  }

  render() {
    if (this.state.error) {
      return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 p-4 sm:p-8 flex items-center justify-center">
            <div className="max-w-2xl w-full bg-white dark:bg-gray-800 rounded-xl border border-red-300 dark:border-red-700 p-6 text-center">
                <h1 className="text-2xl font-bold text-red-600 dark:text-red-400 mb-2">application error</h1>
                <p className="text-gray-600 dark:text-gray-400 mb-4">
                    a critical error occurred and the application could not be loaded.
                    please check the browser console (f12) for details and try reloading the page.
                </p>
                <pre className="mt-4 p-3 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 rounded text-xs text-left whitespace-pre-wrap break-all">
                    <code>{this.state.error.toString()}</code>
                </pre>
            </div>
        </div>
      );
    }
    return this.props.children;
  }
}

