      setError(null);
    } catch (e) {
      console.warn("API fetch failed, using static fallback data.", e);
      setError("backend offline. displaying static data.");
      setAgents(staticAgents);
      setRituals(staticRituals);
      setStatus('success');
    }
  }, []);

  useEffect(() => {
    fetchData();

    const unsubscribe = constellationSocket.subscribe((data: any) => {
        if (data.type === 'agent_status_update' && data.payload) {
            setAgents(prev => prev.map(a => a.id === data.payload.id ? { ...a, ...data.payload } : a));
        } else if (data.type === 'ritual_update' && data.payload) {
            setRituals(prev => prev.map(r => r.id === data.payload.id ? { ...r, ...data.payload } : r));
        }
    });
    constellationSocket.connect();

    return () => {
        unsubscribe();
        constellationSocket.disconnect();
    };
  }, [fetchData]);

  useEffect(() => {
    if (agents.length === 0 || prevAgentsRef.current.length === 0) {
      prevAgentsRef.current = agents;
      return;
    }
    const newPulsing = new Set<string>();
    agents.forEach(agent => {
      const prevAgent = prevAgentsRef.current.find(p => p.id === agent.id);
      if (prevAgent && prevAgent.status !== agent.status) {
        newPulsing.add(agent.id);
      }
    });

    if (newPulsing.size > 0) {
      setPulsingAgents(newPulsing);
      const timer = setTimeout(() => setPulsingAgents(new Set()), 2000);
      return () => clearTimeout(timer);
    }
    prevAgentsRef.current = agents;
  }, [agents]);

  const agentGrid = useMemo(() => {
    const grid: (Agent | null)[][] = Array(3).fill(null).map(() => Array(3).fill(null));
    if (!agents.length) return grid;
    agents.forEach(agent => {
        try {
            const [rowStart, colStart] = agent.position.gridArea.split(' / ').map(Number);
            if(rowStart > 0 && colStart > 0 && rowStart <= 3 && colStart <= 3) {
                grid[rowStart - 1][colStart - 1] = agent;
            }
        } catch (e) {
            console.error(`Invalid gridArea for agent ${agent.id}: ${agent.position.gridArea}`);
        }
    });
    return grid;
  }, [agents]);

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      setSelectedItem(null);
      return;
    }

    if (!selectedItem || !('glyph' in selectedItem)) return; // Only navigate agents

    const findCurrentPos = () => {
        for (let r = 0; r < 3; r++) {
            for (let c = 0; c < 3; c++) {
                if (agentGrid[r][c]?.id === selectedItem.id) return { r, c };
            }
        }
        return null;
    };

    const currentPos = findCurrentPos();
    if (!currentPos) return;

    let { r, c } = currentPos;
    let dr = 0, dc = 0;

    switch (e.key) {
      case 'ArrowUp': dr = -1; break;
      case 'ArrowDown': dr = 1; break;
      case 'ArrowLeft': dc = -1; break;
      case 'ArrowRight': dc = 1; break;
      default: return;
    }

    e.preventDefault();

    for (let i = 1; i < 9; i++) {
        const nr = (r + dr * i + 3) % 3;
        const nc = (c + dc * i + 3) % 3;
        if(agentGrid[nr][nc]) {
            setSelectedItem(agentGrid[nr][nc]);
            return;
        }
    }
  }, [selectedItem, agentGrid]);

  useEffect(() => {
    if (selectedItem) {
      document.addEventListener('keydown', handleKeyDown);
    }
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    }
  }, [selectedItem, handleKeyDown]);

  const centralNode = agents.find((a) => a.id === "kortana");
  const satelliteNodes = agents.filter((a) => a.id !== "kortana");
  const agentCoordMap = new Map<string, { x: number; y: number }>(agents.map(a => [a.id, a.position.coords]));

  const getRitualPositions = (count: number) => {
    const positions = [];
    const radius = 48;
    const centerX = 50, centerY = 50;
    for (let i = 0; i < count; i++) {
        const angle = (i / count) * 2 * Math.PI;
        positions.push({ x: centerX + radius * Math.cos(angle), y: centerY + radius * Math.sin(angle) });
    }
    return positions;
  };
  const ritualPositions = getRitualPositions(rituals.length);

  return (
    <div className="bg-gray-900 min-h-[calc(100vh-65px)] p-4 sm:p-8 text-gray-100 flex flex-col items-center justify-center relative overflow-hidden">
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_80%_80%_at_50%_-20%,rgba(129,140,248,0.3),rgba(255,255,255,0))] opacity-50" />
      <div className="text-center z-10 mb-8 sm:mb-12">
        <h2 className="text-3xl sm:text-4xl font-bold text-indigo-400" style={{ textShadow: "0 0 8px rgba(129,140,248,0.5)" }}>
          covenant constellation
        </h2>
        {status === 'loading' && <p className="text-md sm:text-lg text-gray-400 flex items-center justify-center gap-2"><Loader size={16} className="animate-spin" /> connecting...</p>}
        {error && <p className="text-xs text-yellow-400 flex items-center justify-center gap-2"><AlertTriangle size={14} /> {error}</p>}
        {status === 'success' && !error && <p className="text-md sm:text-lg text-gray-400">agent network status: online</p>}
      </div>

      <div className="relative w-full max-w-4xl aspect-square">
        {status === 'loading' && <div className="absolute inset-0 flex items-center justify-center"><Loader size={48} className="animate-spin text-indigo-500" /></div>}
        {status === 'success' && <>
          <div className="grid grid-cols-3 grid-rows-3 w-full h-full gap-2 sm:gap-4">
            {agents.map((agent) => (
              <div key={agent.id} style={{ gridArea: agent.position.gridArea }} className={`group relative flex items-center justify-center p-1 sm:p-2 ${pulsingAgents.has(agent.id) ? 'animate-pulse-glow' : ''}`}>
                <AgentCard agent={agent} onClick={() => setSelectedItem(agent)} />
                 <div className="absolute bottom-full mb-2 w-max max-w-xs p-3 bg-gray-950 border border-indigo-800 text-white text-xs rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-20 shadow-lg">
                    <p><strong className="font-semibold text-indigo-400">purpose:</strong> {agent.purpose}</p>
                    {agent.emotionalPulse && <p className="mt-1"><strong className="font-semibold text-indigo-400">pulse:</strong> {agent.emotionalPulse}</p>}
                </div>
              </div>
            ))}
          </div>

           {rituals.map((ritual, i) => (
             <RitualNode key={ritual.id} ritual={ritual} position={ritualPositions[i]} isSelected={selectedItem?.id === ritual.id} onClick={() => setSelectedItem(ritual)} />
           ))}

          <svg className="absolute inset-0 w-full h-full opacity-30 pointer-events-none">
            {centralNode && satelliteNodes.map((agent) => (
              <line key={`line-${agent.id}`} x1={`${centralNode.position.coords.x}%`} y1={`${centralNode.position.coords.y}%`} x2={`${agent.position.coords.x}%`} y2={`${agent.position.coords.y}%`} className="stroke-indigo-500" strokeWidth="1" style={{ strokeDasharray: "5 5", animation: "pulse-line 2s linear infinite" }} />
            ))}
            {rituals.map((ritual, i) => (
                ritual.agentIds.map(agentId => {
                    const agentCoords = agentCoordMap.get(agentId);
                    if (!agentCoords) return null;
                    return <line key={`ritual-line-${ritual.id}-${agentId}`} x1={`${ritualPositions[i].x}%`} y1={`${ritualPositions[i].y}%`} x2={`${agentCoords.x}%`} y2={`${agentCoords.y}%`} className="stroke-purple-500" strokeWidth="0.5" strokeDasharray="2 3" />
                })
            ))}
          </svg>
        </>}
      </div>
      {selectedItem && <DetailModal item={selectedItem} onClose={() => setSelectedItem(null)} />}
    </div>
  );
}

