import React, { useState, useEffect, useCallback } from 'react';
import { Check, Clock, Zap, UserCheck, Cpu, Laptop, ChevronDown, AlertTriangle, RefreshCw, Server, Loader } from 'lucide-react';
import { getHealthStatus } from '../services/apiService';

// Refactored to be a controlled component for better parent-level management (e.g., Expand All).
// Added ARIA improvements, unique IDs, and respects reduced motion preference.
const LogSection = ({ id, title, children, noPadding, isExpanded, onToggle }: React.PropsWithChildren<{ id: string, title: string, noPadding?: boolean, isExpanded: boolean, onToggle: () => void }>) => {
  const headerId = `log-section-header-${id}`;
  const contentId = `log-section-content-${id}`;

  return (
    <div className="bg-gray-800/50 rounded-xl border border-gray-700 mb-6 overflow-hidden">
       <button
        id={headerId}
        className="w-full text-left flex items-center justify-between text-xl font-semibold text-indigo-300 border-b border-gray-700 px-6 py-3 hover:bg-gray-700/50 transition-colors"
        onClick={onToggle}
        aria-expanded={isExpanded}
        aria-controls={contentId}
      >
        <span>{title}</span>
        <ChevronDown
          size={20}
          className={`transform motion-safe:transition-transform motion-safe:duration-300 ${isExpanded ? 'rotate-180' : 'rotate-0'}`}
        />
      </button>
      <div
        id={contentId}
        role="region"
        aria-labelledby={headerId}
        className={`motion-safe:transition-[max-height] motion-safe:duration-500 motion-safe:ease-in-out overflow-hidden ${isExpanded ? 'max-h-[2000px]' : 'max-h-0'}`}
      >
        <div className={`space-y-3 text-gray-300 ${noPadding ? '' : 'p-6'}`}>{children}</div>
      </div>
    </div>
  );
};

const HealthItem = ({ children }: React.PropsWithChildren<{}>) => (
  <li className="flex items-start gap-2">
    <Check size={16} className="text-green-400 mt-1 shrink-0" />
    <span>{children}</span>
  </li>
);

const TimelineItem = ({ time, status, children }: React.PropsWithChildren<{ time: string, status: 'ACTIVE' | 'PENDING' }>) => {
    const icon = status === 'ACTIVE'
        ? <Zap size={16} className="text-yellow-400 animate-pulse" />
        : <Clock size={16} className="text-gray-500" />;
    return (
        <div className="flex items-center gap-4 py-2 border-b border-gray-700/50 last:border-b-0">
            <div className="w-8 shrink-0 flex justify-center">{icon}</div>
            <div className="w-24 shrink-0 font-mono text-sm">{time}</div>
            <div className="text-sm">{children}</div>
        </div>
    );
};

const ActionList = ({ title, icon, items }: { title: string, icon: React.ReactNode, items: string[] }) => (
    <div>
        <h4 className="font-semibold text-indigo-400 mb-2 flex items-center gap-2">{icon}{title}</h4>
        <ol className="list-decimal list-inside space-y-1 pl-2 text-sm">
            {items.map((item, i) => <li key={i}>{item}</li>)}
        </ol>
    </div>
);

const BackendHealthStatusDisplay: React.FC = () => {
    const [status, setStatus] = useState<'loading' | 'online' | 'offline'>('loading');
    const [backendInfo, setBackendInfo] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    const checkHealth = useCallback(async () => {
        setStatus('loading');
        setError(null);
        try {
            const data = await getHealthStatus();
            setStatus('online');
            setBackendInfo(data.backend || 'unknown');
        } catch (e) {
            console.error("Backend health check failed:", e);
            setStatus('offline');
            setError('could not connect to backend. is the python server running?');
        }
    }, []);

    useEffect(() => {
        checkHealth();
        const interval = setInterval(checkHealth, 30000); // Check every 30 seconds
        return () => clearInterval(interval);
    }, [checkHealth]);

    return (
        <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-700/50 mb-4">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Server size={20} className="text-indigo-400" />
                    <h4 className="font-semibold text-indigo-400">Backend API Status</h4>
                </div>
                <button onClick={checkHealth} disabled={status === 'loading'} className="p-1 rounded-md hover:bg-gray-700/50 disabled:opacity-50" aria-label="Refresh backend status">
                    <RefreshCw size={16} className={status === 'loading' ? 'animate-spin' : ''} />
                </button>
            </div>
            <div className="mt-2 text-sm">
                {status === 'loading' && <p className="text-gray-500 flex items-center gap-2"><Loader size={16} className="animate-spin" /> checking...</p>}
                {status === 'online' && <p className="text-green-400 flex items-center gap-2"><Check size={16} /> online (backend: {backendInfo})</p>}
                {status === 'offline' && <p className="text-red-400 flex items-center gap-2"><AlertTriangle size={16} /> offline: {error}</p>}
            </div>
        </div>
    );
};


